fn binary_search(a: &Vec<i32>, key: i32) -> usize {
    let mut left = 0;
    let mut right = a.len();
    while left < right {
        let mid = left + (right - left) / 2;
        if a[mid] < key {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    left
}

